const chapters={foyer:{name:'THE FOYER',num:'01 / 06',mark:'I',class:'foyer'},kitchen:{name:'THE KITCHEN',num:'02 / 06',mark:'II',class:'kitchen'},study:{name:'THE STUDY',num:'03 / 06',mark:'III',class:'study'},nursery:{name:'THE UPSTAIRS ROOM',num:'04 / 06',mark:'IV',class:'upstairs'},basement:{name:'THE BASEMENT',num:'05 / 06',mark:'V',class:'basement'},ending:{name:'THE THRESHOLD',num:'06 / 06',mark:'VI',class:'threshold'},memory:{name:'THE HOUSE BETWEEN',num:'06 / 06',mark:'VI',class:'memory'}};
const has=(item)=>state.inventory.includes(item);
function give(item,label){if(has(item))return false;state.inventory.push(item);journal(`FOUND: ${label}.`);toast(`Added to your pockets · ${label}`);return true}
function journal(text){state.journal.push(text);if(state.journal.length>24)state.journal.shift()}
function toast(text){ui.toast.textContent=text;ui.toast.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>ui.toast.classList.remove('show'),2200)}
function save(){try{localStorage.setItem('house-between-save',JSON.stringify(state));ui.save.textContent='NIGHT SAVED'}catch{ui.save.textContent='LOCAL SAVE UNAVAILABLE'}}
function load(){try{const x=JSON.parse(localStorage.getItem('house-between-save'));if(x&&x.flags&&Array.isArray(x.inventory)&&x.scene){state={...fresh(),...x};return true}}catch{}return false}
function enter(scene){state.scene=scene;state.visited[scene]=true;ui.journal.hidden=true;ui.journalToggle.innerHTML='JOURNAL <span>＋</span>';render();save();window.scrollTo({top:0,behavior:'smooth'})}
function act(key){
  switch(key){
    case'kitchen':enter('kitchen');break;
    case'study':enter('study');break;
    case'upstairs':if(!has('iron key')){toast('The upstairs door is locked.');state.tension=Math.min(5,state.tension+1);journal('The upstairs door is locked. Something waits on the other side.');save();render()}else enter('nursery');break;
    case'basement':if(!has('iron key')){toast('The basement door will not budge.');state.tension=Math.min(5,state.tension+1);save();render()}else enter('basement');break;
    case'call':state.tension=Math.min(5,state.tension+1);journal('A voice from upstairs said your name. You did not answer.');state.flags.heardCall=true;render();save();break;
    case'door':if(!state.flags.power){state.tension=Math.min(5,state.tension+1);toast('The deadbolt is warm. It will not turn.');journal('The front door is locked from the other side.');render();save()}else end('escape');break;
    case'shelves':if(give('brass token','a brass token'))state.flags.token=true;else toast('You already searched the shelves.');render();save();break;
    case'desk':if(!has('brass token')){toast('A small round slot. Something is missing.');state.flags.deskSeen=true;journal('The desk has a little brass lock.');render();save()}else if(!state.flags.desk){state.flags.desk=true;give('iron key','the iron key');give('letter','June’s letter');state.flags.letter=true;render();save()}else toast('The desk is empty.');break;
    case'counter':if(give('fuse','a ceramic fuse'))state.flags.fuse=true;render();save();break;
    case'fridge':if(!state.flags.recipe){state.flags.recipe=true;give('matchbook','a damp matchbook');journal('A note on the fridge: “If the hall light goes out, count the knocks.”');}else toast('The note is soft with age.');render();save();break;
    case'photo':if(!state.flags.photo){state.flags.photo=true;give('photograph','a creased photograph');journal('The photograph shows you and June in this house, years ago. On the back: “You promised you would come back.”');}else toast('You already have the photograph.');render();save();break;
    case'record':if(!state.flags.record){state.flags.record=true;give('voice cylinder','June’s voice');journal('The cylinder turns. June’s voice: “I’m not in the house. I’m in what you remember.”');state.tension=Math.max(0,state.tension-1);}else toast('The cylinder has nothing more to say.');render();save();break;
    case'panel':if(!state.flags.fuseIn){if(!has('fuse')){toast('The fuse is missing.');return}state.flags.fuseIn=true;state.flags.power=true;state.tension=Math.max(0,state.tension-1);journal('The lights come back. In the sudden hum, you hear rain at the front door.');toast('Power restored.');}render();save();break;
    case'markings':if(!state.flags.markings){state.flags.markings=true;journal('Scratched into the basement wall: 2:17. June’s birthday.');toast('A date you remember.');}render();save();break;
    case'return':enter('foyer');break;
    case'truth':end('truth');break;
    case'leave':end('escape');break;
    case'wait':end('wait');break;
    case'restart':restart();break;
  }
}
function end(type){state.ending=type;state.scene='ending';if(type==='truth')state.flags.truth=true;journal(type==='truth'?'You say June’s name without asking the house to give her back.':'You step into the night and leave the house behind.');save();render()}
function option(label,detail,key,disabled=false){return {label,detail,key,disabled}}
function getScene(){
 const f=state.flags,sc=state.scene;
 if(sc==='foyer'){
  const choices=[option('Go to the kitchen','The old fuse box used to be under the stairs.','kitchen'),option('Search the study','The door is ajar. The dark inside is familiar.','study'),option('Try the upstairs door',has('iron key')?'The voice is waiting in the room at the end.':'It is locked. Something shifts behind it.','upstairs'),...(has('iron key')?[option('Go down to the basement','The breaker panel is below.','basement')]:[]),option('Call out','Only say her name if you are ready to hear it back.','call'),option('Try the front door',f.power?'Rain. The open night.':'The deadbolt will not move.','door')];
  return {title:'The door was already open.',kicker:'NIGHT ONE · 2:17 AM',copy:`<p>You came back to the house for your sister. <em>June</em> disappeared here twelve years ago, and the town learned to stop asking.</p><p>The hall smells of wet wool and cold dust. Upstairs, a floorboard creaks—three slow knocks, exactly like the ones you used to tap against her bedroom wall.</p>${state.tension>=3?'<p><em>At the edge of the light, a figure stands with its back to you.</em> You blink. The hall is empty.</p>':''}`,choices};
 }
 if(sc==='kitchen')return {title:f.fuse?'The kitchen keeps its secrets.':'A house can hide in plain sight.',kicker:'THE KITCHEN · THE COLD ROOM',copy:`<p>The fridge hums though the power is out. A family calendar curls at the corners; every date after June’s birthday has been crossed out in your handwriting.</p>${f.fuse?'<p>The cabinet beneath the sink hangs open. The empty space where the fuse sat looks like a missing tooth.</p>':'<p>Under the sink, behind a bottle of bleach, there is a ceramic fuse. On the fridge, a note in June’s hand.</p>'}`,choices:[...(!f.fuse?[option('Take the fuse','It is still clean. Still useful.','counter')]:[]),...(!f.recipe?[option('Read the note on the fridge','A small, ordinary instruction.','fridge')]:[]),option('Return to the foyer','The hall waits in the dark.','return')]};
 if(sc==='study')return {title:f.desk?'The desk is open.':'Everything is where you left it.',kicker:'THE STUDY · DUST & PAPER',copy:`<p>Your father’s study. The books are swollen with damp. A desk lamp points at the wall as if someone has just stood up from it.</p>${!f.token?'<p>On the bookshelf, a brass token glints between two old encyclopedias. The desk drawer has a matching round lock.</p>':f.desk?'<p>June’s letter is folded around a small iron key. Her handwriting has not changed.</p>':'<p>The brass token fits the little lock on the desk. A drawer waits inside.</p>'}${f.letter?'<p><em>“You said you would come back for me. I know you were scared. I was scared too.”</em></p>':''}`,choices:[...(!f.token?[option('Search between the books','Something brass catches the light.','shelves')]:[]),...(!f.desk?[option('Try the desk drawer',f.token?'Use the brass token.':'It has a small, round lock.','desk')]:[]),option('Return to the foyer','The hallway feels longer now.','return')]};
 if(sc==='nursery')return {title:f.record?'A voice, not a ghost.':'The room at the end of the hall.',kicker:'UPSTAIRS · JUNE’S ROOM',copy:`<p>The door opens with a sigh. The little room has been kept exactly as you remember it: moon stickers, a narrow bed, a record player with a clear cylinder beneath its dust cover.</p>${f.photo?'<p>The photograph in your pocket is warm. In it, June is grinning at the camera. You are holding her hand.</p>':'<p>A photograph lies face down on the sill. Someone has written on its back.</p>'}${f.record?'<p><em>Her voice came from the cylinder, thin and bright. Not a ghost. Just a memory you could finally hear.</em></p>':'<p>The record player is wound. It only needs a hand to turn the crank.</p>'}`,choices:[...(!f.photo?[option('Turn over the photograph','A promise in your own handwriting.','photo')]:[]),...(!f.record?[option('Play the voice cylinder','Listen without asking it to answer.','record')]:[]),option('Return to the foyer','Leave the room as you found it.','return')]};
 if(sc==='basement')return {title:f.power?'The lights wake up.':'The dark has a pulse.',kicker:'BELOW THE HOUSE · THE BREAKER',copy:`<p>The basement is all pipes and old stone. The breaker panel hangs crooked on the wall; one fuse is missing.</p>${f.power?'<p>In the light, you notice a date scratched into the plaster: <em>2:17</em>. The rain on the other side of the door sounds almost like applause.</p>':has('fuse')?'<p>The ceramic fuse from the kitchen fits. Somewhere above you, the house is holding its breath.</p>':'<p>Someone has scratched a date into the plaster beside the panel. You cannot see it clearly in the dark.</p>'}${f.markings?'<p><em>2:17. June’s birthday. Not the time she disappeared.</em></p>':''}`,choices:[...(!f.power&&has('fuse')?[option('Replace the fuse','One click. Then every light in the house.','panel')]:[]),...(!f.markings?[option('Look closer at the wall','The scratches catch the weak light.','markings')]:[]),option('Return to the foyer','One climb back into the house.','return')]};
 if(sc==='ending'&&state.ending==='truth')return {title:'You remember her as she was.',kicker:'ENDING · WHAT WE CARRY',copy:`<span class="ending-stamp">THE TRUE ENDING</span><p>You speak June’s name. Not as a question. Not as a bargain.</p><p>The house gives nothing back. The room upstairs is only a room; the voice was only a voice, saved in the patient grooves of a cylinder. She was real. She loved you. You were children, and the night was not your fault.</p><p>When morning arrives, the open door is just a door. You carry the photograph into the rain.</p>`,choices:[option('Begin again','Some nights deserve another telling.','restart')]};
 if(sc==='ending'&&state.ending==='wait')return {title:'The house keeps you.',kicker:'ENDING · THE OLD PROMISE',copy:`<span class="ending-stamp">A QUIETER ENDING</span><p>You turn away from the open door. Upstairs, a floorboard creaks—three slow knocks.</p><p>This time, you answer. The sound travels through the house and comes back softer, like someone answering from very far away. You stay until the rain stops. Then you stay until you cannot remember what you were waiting for.</p>`,choices:[option('Try the door again','The night is not over.','restart')]};
 if(sc==='ending')return {title:'The night lets you go.',kicker:'ENDING · OUT INTO THE RAIN',copy:`<span class="ending-stamp">AN ENDING</span><p>The lock turns. Cold rain finds your face. Behind you, the house gives a long, settling groan, like a person finally falling asleep.</p><p>You leave without knowing what waited upstairs. You can live with that. For tonight.</p>`,choices:[option('Start another night','There is more to remember.','restart')]};
 return {title:'The house between.',kicker:'NIGHT ONE',copy:'The house is quiet.',choices:[]};
}

