 ui.save.textContent='NEW NIGHT';ui.begin.innerHTML='ENTER THE HOUSE <span>→</span>';ui.intro.classList.remove('hidden');render();
}
function toggleSound(){
 const button=$('#sound-toggle');
 if(audio){audio.oscillators.forEach(o=>{try{o.stop()}catch{}});audio.context.close();audio=null;button.classList.remove('active');button.setAttribute('aria-pressed','false');toast('Ambience off.');return}
