$('#begin').addEventListener('click',()=>{ui.intro.classList.add('hidden');render();if(!state.journal.length)journal('The front door stood open when you arrived.');save()});
$('#restart').addEventListener('click',restart);
$('#sound-toggle').addEventListener('click',toggleSound);
ui.journalToggle.addEventListener('click',()=>{ui.journal.hidden=!ui.journal.hidden;ui.journalToggle.innerHTML=ui.journal.hidden?'JOURNAL <span>＋</span>':'JOURNAL <span>−</span>';if(!ui.journal.hidden)ui.journal.scrollTop=0});
document.addEventListener('keydown',event=>{
 if(event.key==='Escape'&&!ui.journal.hidden){ui.journal.hidden=true;ui.journalToggle.innerHTML='JOURNAL <span>＋</span>';return}
 if(!ui.intro.classList.contains('hidden')){if(event.key==='Enter'||event.key===' '){event.preventDefault();ui.begin.click()}return}
 if(/^[1-9]$/.test(event.key)){const button=ui.choices.querySelectorAll('button')[Number(event.key)-1];if(button&&!button.disabled)button.click()}
});
const hasSave=load();
if(hasSave){ui.save.textContent='NIGHT SAVED';ui.begin.innerHTML='CONTINUE NIGHT <span>→</span>'}else ui.save.textContent='NEW NIGHT';
render();
</script>

