+function render(){
+ const scene=getScene(), chapter=chapters[state.scene]||chapters.foyer;
+ ui.title.textContent=scene.title;ui.copy.innerHTML=scene.copy;ui.kicker.textContent=scene.kicker;ui.mark.textContent=chapter.mark;
+ ui.chapter.textContent=state.ending?'THE HOUSE BETWEEN':chapter.name;
+ ui.sceneNum.textContent=chapter.num;ui.sceneName.textContent=chapter.name;
+ ui.art.className=`scene-art ${chapter.class}${state.ending==='truth'?' ending':''}`;
+ ui.tension.style.width=`${Math.max(0,Math.min(5,state.tension))*20}%`;
+ ui.tensionLabel.textContent=state.tension>=4?'CLOSE':state.tension>=2?'RESTLESS':'QUIET';
+ ui.tensionLabel.style.color=state.tension>=4?'#df806f':state.tension>=2?'#c28a72':'';
+ ui.choices.replaceChildren();
+ scene.choices.forEach((choice,index)=>{
+  const button=document.createElement('button');button.type='button';button.className='choice';button.disabled=!!choice.disabled;
+  button.setAttribute('aria-label',`${index+1}. ${choice.label}${choice.detail?`. ${choice.detail}`:''}`);
+  button.append(document.createTextNode(choice.label));
+  if(choice.detail){const small=document.createElement('small');small.textContent=choice.detail;button.append(small)}
+  button.addEventListener('click',()=>act(choice.key));ui.choices.append(button);
+ });
+ ui.inventory.replaceChildren();
+ if(!state.inventory.length){const empty=document.createElement('span');empty.className='empty-inventory';empty.textContent='Nothing but the cold.';ui.inventory.append(empty)}
+ else state.inventory.forEach(item=>{const el=document.createElement('span');el.className='item';el.textContent=item.toUpperCase();ui.inventory.append(el)});
+ const sequence=['foyer','kitchen','study','nursery','basement','ending'];ui.dots.replaceChildren();
+ sequence.forEach(key=>{const dot=document.createElement('i');if(state.visited[key]||key==='ending'&&state.ending)dot.className='done';dot.setAttribute('aria-label',key);ui.dots.append(dot)});
+ ui.journal.replaceChildren();const journalHead=document.createElement('div');journalHead.className='eyebrow';journalHead.textContent='THINGS YOU REMEMBER';ui.journal.append(journalHead);
+ if(state.journal.length){state.journal.slice().reverse().forEach(entry=>{const p=document.createElement('p');p.textContent=entry;ui.journal.append(p)})}
+ else{const p=document.createElement('p');p.textContent='The page is still blank.';ui.journal.append(p)}
+}
+function restart(){
+ if(!window.confirm('Start a new night? Your saved story will be replaced.'))return;
+ state=fresh();try{localStorage.removeItem('house-between-save')}catch{}
+ ui.save.textContent='NEW NIGHT';ui.begin.innerHTML='ENTER THE HOUSE <span>→</span>';ui.intro.classList.remove('hidden');render();
+}
+function toggleSound(){
+ const button=$('#sound-toggle');
+ if(audio){audio.oscillators.forEach(o=>{try{o.stop()}catch{}});audio.context.close();audio=null;button.classList.remove('active');button.setAttribute('aria-pressed','false');toast('Ambience off.');return}
+ try{
+  const context=new(window.AudioContext||window.webkitAudioContext)(),gain=context.createGain();gain.gain.value=.018;gain.connect(context.destination);
+  const oscillators=[55,55.7].map((frequency,index)=>{const o=context.createOscillator(),g=context.createGain();o.type=index?'sine':'triangle';o.frequency.value=frequency;g.gain.value=index?.35:.65;o.connect(g);g.connect(gain);o.start();return o});
+  audio={context,oscillators};button.classList.add('active');button.setAttribute('aria-pressed','true');toast('A low house-hum, just beneath the rain.');
+ }catch{toast('Ambient audio is unavailable in this browser.')}
+}
